 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr - 1, cc), (rr + 1, cc), (rr, cc - 1), (rr, cc + 1)):
                    if 0 <= nr < h and 0 <= nc < w and (nr, nc) not in seen and grid[nr][nc] == color:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            min_r = min(rr for rr, _ in cells)
            max_r = max(rr for rr, _ in cells)
            min_c = min(cc for _, cc in cells)
            max_c = max(cc for _, cc in cells)
            objects.append((min_c, color, [(rr - min_r, cc - min_c) for rr, cc in cells], max_r - min_r + 1))

    objects.sort(key=lambda obj: obj[0])
    out = [[0] * w for _ in range(h)]
    out_r = 0
    out_c = 0
    for i, (_, color, cells, obj_h) in enumerate(objects):
        for dr, dc in cells:
            rr, cc = out_r + dr, out_c + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
        if i + 1 < len(objects):
            out_r += obj_h - 1
            out_c += 1
    return out
